70 cm"}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Depth: 56 cm"}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Height: 35 cm"})]}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Position:"}),/*#__PURE__*/_jsxs(Box,{sx:{ml:2},children:[/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"33 cm above the floor"}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"55 cm below the upper bench"})]}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Colors:"}),/*#__PURE__*/_jsxs(Box,{sx:{ml:2},children:[/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Outside: White"}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Inside: White"})]}),/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Features:"}),/*#__PURE__*/_jsx(Box,{sx:{ml:2},children:/*#__PURE__*/_jsx(Typography,{variant:"body2",children:"Aluminum Protection Trim (ID: WB-02-P1-LS-PT): Height: 1 cm, Positioned on the edge"})})]})]})]})]})]}),/*#__PURE__*/_jsxs(Box,{sx:{mt:3,display:'flex',justifyContent:'space-between'},children:[/*#__PURE__*/_jsx(Button,{variant:"outlined",disabled:true,children:"Back"}),/*#__PURE__*/_jsx(Button,{variant:"contained",color:"primary",children:"Next"})]})]});};export default TrailerSpecification;

